globalCSS:
/* ==========================================================
 * Sola Flame (Autumnal Hearth) — Custom CSS for Lumiverse
 * Canonical 16-Color Palette Integration
 * ========================================================== */

:root {
  /* Sola Canonical Gradients */
  --sola-solstice: linear-gradient(135deg, #F4A261 0%, #EE6C4D 100%);
  --sola-hearth: linear-gradient(135deg, #E07A5F 0%, #C06C54 100%);
  --sola-dusk: linear-gradient(135deg, #F3B74B 0%, #8592E6 100%);

  /* Text Selection */
  --sola-selection-bg: rgba(238, 108, 77, 0.35);
  --sola-selection-text: #FDF6F0;
}

/* Atmospheric Selection */
::selection {
  background: var(--sola-selection-bg);
  color: var(--sola-selection-text);
}

/* Sola Smooth Scrollbar */
::-webkit-scrollbar {
  width: 7px;
  height: 7px;
}
::-webkit-scrollbar-track {
  background: transparent;
}
::-webkit-scrollbar-thumb {
  background: rgba(224, 122, 95, 0.28);
  border-radius: 9999px;
  border: 1px solid rgba(238, 108, 77, 0.15);
}
::-webkit-scrollbar-thumb:hover {
  background: rgba(238, 108, 77, 0.5);
}

/* Sola Dialogue & Thoughts Highlight Invariants */
.prose em,
[data-component="MessageContent"] em {
  color: #F3B74B !important; /* Amber Interiority */
  font-style: italic;
}

.prose q,
.proseDialogue,
[data-component="MessageContent"] q {
  color: #F4A261 !important; /* Marigold Dialogue */
}

.prose blockquote {
  border-left: 3px solid #E07A5F !important;
  background: rgba(224, 122, 95, 0.06);
  padding: 8px 14px;
  border-radius: 0 8px 8px 0;
  color: rgba(253, 246, 240, 0.85);
}

/* Solstice Radiant CTA Buttons */
button[data-variant="primary"],
.btnPrimary {
  background: linear-gradient(135deg, #F4A261 0%, #EE6C4D 100%) !important;
  color: #120D0B !important;
  font-weight: 600;
  border: 1px solid rgba(244, 162, 97, 0.3) !important;
  box-shadow: 0 2px 12px rgba(238, 108, 77, 0.25) !important;
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
}

button[data-variant="primary"]:hover,
.btnPrimary:hover {
  background: linear-gradient(135deg, #F5AC73 0%, #F07A5D 100%) !important;
  box-shadow: 0 4px 18px rgba(238, 108, 77, 0.42) !important;
  transform: translateY(-1px);
}

/* Focus Rings */
:focus-visible {
  outline: 2px solid rgba(238, 108, 77, 0.6) !important;
  outline-offset: 2px;
}
